-- Prod sd-main project + sdteam connection (2026-07-07). Idempotent.
-- Creates the standing `sd-main` project (same id as the local/staging clone,
-- so daemon-per-dev dev_apps mappings carry over), copies its full hardening
-- (qa_manifest, conventions, qa_smoke_url, sprint_mode) from the reviewed
-- local settings, binds the repo, registers the four sdteam boxes
-- (per-dev jamshid/shahzod scoped to sd-main; agora-cs -> sd-cs; sandbox =
-- shared sd-main box), and adds the QA regression autopilot.
--
-- Run: cat scripts/prod-sdmain-sdteam-2026-07-07.sql | fly ssh console -a sd-agora-db -C 'psql -U agora -d agora'

-- 1) the project itself (full settings from the hardened local copy)
INSERT INTO project (id, workspace_id, title, description, status, priority, settings)
VALUES ('cd57610b-7bb8-482e-90c6-8285029d0432','356e2301-64fd-440b-ab68-7fcfa76088b1','sd-main',
        'SalesDoctor main dealer-CRM monolith (Yii/PHP). Standing project for sd-main code work; Bitrix sprints attach their tasks here for QA/regression.',
        'in_progress','high', $sdmain${"kb_skill": "sd-main-kb", "risk_map": [{"tier": "critical", "notes": "money movement (Payme/Click, invoices, balances) — a silent regression here costs real money", "paths": ["protected/modules/pay/**", "protected/modules/payment/**", "protected/modules/finans/**", "protected/modules/rating/**"], "module": "billing/payments"}, {"tier": "critical", "notes": "the golden path of the business; order-creation lock path is deadlock-prone", "paths": ["protected/modules/orders/**", "protected/models/Order.php"], "module": "orders core"}, {"tier": "critical", "notes": "StoreDetail::update_count() is the hottest write path — read doc/store_detail_deadlock_analysis.md first", "paths": ["protected/models/StoreDetail.php", "protected/modules/stock/**", "protected/modules/warehouse/**", "protected/modules/inventory/**", "protected/components/LotDistribution.php"], "module": "stock/warehouse integrity"}, {"tier": "critical", "notes": "blast radius = every tenant; an unscoped cache key leaks data across distributors", "paths": ["protected/components/Distr.php", "protected/components/TenantContext.php", "protected/components/ScopedCache.php", "protected/components/FilialComponent.php", "protected/components/Queue.php", "protected/components/DbAuthManager.php", "protected/components/WebUser.php"], "module": "tenancy/cache/queue infra"}, {"tier": "critical", "notes": "FROZEN — never modify; mobile clients in the wild depend on the exact shape", "paths": ["protected/modules/api/**", "protected/modules/api2/**", "protected/modules/api3/**"], "module": "frozen mobile APIs"}, {"tier": "guarded", "notes": "additive-only contract: add fields, never remove/rename/retype; opt-in flags for shape changes", "paths": ["protected/modules/api4/**"], "module": "api4 (current mobile API)"}, {"tier": "guarded", "notes": "consumed by pages pinned to 5 different Vue versions — verify one consumer per version or scope the change page-local", "paths": ["protected/views/vue/**", "js/vue/**"], "module": "shared Vue components"}, {"tier": "guarded", "notes": "10k-16k LOC files — smallest targeted edit only, never reformat", "paths": ["protected/modules/**/ZagruzGroupOverhead.php", "protected/modules/gps2/**", "protected/modules/gps3/**"], "module": "god files"}, {"tier": "guarded", "notes": "external contracts (1C, marking, partners) — breakage surfaces off-platform", "paths": ["protected/modules/sync/**", "protected/modules/integration/**", "protected/modules/markirovka/**", "protected/modules/neakb/**"], "module": "sync/integrations"}, {"tier": "safe", "notes": "read paths; still verify the page renders on the QA box", "paths": ["protected/modules/report/**", "protected/modules/dashboard/**"], "module": "reports/dashboard (read-only)"}, {"tier": "safe", "notes": "add keys to ALL locales (ru,en,uz,fa,tr)", "paths": ["protected/messages/**"], "module": "i18n messages"}], "docs_repo": "ssh://git@ssh-gitlab.sdteam.uz:2222/j.tulaganov/sales-doctor-docs.git", "conventions": "## sd-main coding conventions (Yii 1.x legacy ERP — 10 years, multi-tenant, no build step)\n\n### Ground rules\n- Integration branch is `billing` (protected). Branch off it, open a PR against it; NEVER commit/push/merge to `billing` directly. `master` is NOT the integration branch.\n- Keep diffs SMALL and scoped to the ticket. No drive-by refactors, no reformatting, no renames outside the task.\n- Verification happens ONLY on the QA boxes (sdteam.uz) — the repo is not locally runnable (no PHP runtime, `framework/` is host-provided, migrations live on the prod host). Never claim \"tested locally\".\n- Reply to issues/comments in the issue's language (Russian/Uzbek); code identifiers and commit messages in English.\n\n### Backend (PHP / Yii 1.x)\n- Two controller patterns, pick by LOCATION: Pattern A = layered action classes (controller `actions()` map → `ApiAction` subclass → validator → service → transformer) — the target shape for `api4` and any NEW module. Pattern B = fat controller actions (`actionList()`/`actionEdit()` inline) — older modules (`orders`, `stock`, `finans`, `settings`). When fixing a Pattern B bug, STAY in Pattern B — no side-quest refactors to Pattern A.\n- Parameterized SQL only: `CDbCriteria` with `:params`, `bindParam`, or ActiveRecord finders. Never interpolate user input into SQL.\n- Statuses/types: extend the model's `public $status = [...]` array — do NOT add `switch` branches for new statuses.\n- i18n: user-facing strings via `Yii::t('main', ...)`; add the key to ALL of `protected/messages/{ru,en,uz,fa,tr}/main.php`. Primary UI language is `ru`.\n- Comment sparingly, matching the file's existing density; Russian/Uzbek-Latin comments are normal — match neighbors.\n- `.obsolete` controllers are kept as reference — do not delete or refactor them.\n- Config: edit `protected/config/main_static.php` (git-tracked). NEVER edit `main.php`, `params.json`, `console.php` — gitignored secret overlays.\n\n### Multi-tenancy (the #1 way to break production)\n- Never hardcode the `d0_` table prefix. Hot tables are per-tenant (`d0_order`, `d0_store_detail`); resolve names via `Model::model()->tableName()`. New hot multi-tenant table → register in `Distr::$prefixTables`. IDs are tenant-prefixed too (`STORE_ID='d0_1'`).\n- Cache: never `Yii::app()->cache->set()` with an unscoped key (leaks across tenants). Go through `ScopedCache->withScope($tenantId, $filialScope)` — it is immutable (returns a new instance), has a 30s circuit breaker on Redis failure; treat `false`/`null` as cache-miss. Redis DB map: 0 = sessions, 1 = queue, 2 = app cache.\n- Central-only mutations (price lists, master catalogs) must check `FilialComponent::isMain()` before writing.\n\n### Hot write paths (deadlock discipline)\n- `StoreDetail` is the hottest, deadlock-prone write path. Before touching `StoreDetail::update_count()` or any order-creation lock path, read `doc/store_detail_deadlock_analysis.md`. Keep a deterministic lock order; NO HTTP I/O or extra logging inside a `StoreDetail` transaction; never call `update_count()` twice for the same row in one transaction.\n\n### API contracts (mobile clients in the wild)\n- `api4` is the current mobile API: changes are ADDITIVE ONLY — add fields, never remove/rename/retype; gate response-shape changes behind an opt-in flag (`?include_x=1`); never tighten validation on an existing endpoint.\n- `api`, `api2`, `api3` are FROZEN — do not modify them.\n- `/api3/login` returns HTTP 200 + HTML (auth redirect) for invalid tokens, not JSON — scripts must check Content-Type before `JSON.parse`.\n\n### Frontend (script-tag islands, NO build step)\n- There is no webpack/vite/gulp and no root `package.json`. JS libs are committed under `vendors/` and `js/` and loaded directly by PHP views. Do not introduce a build step, npm installs, or new framework versions.\n- FIVE coexisting stacks: Vue 2.7 views, Vue 3 views pinned to FOUR different Vue 3 versions per page, jQuery+Bootstrap (most views), AngularJS islands (`ng-modules/`). Before editing a view, identify WHICH stack and WHICH version that page loads (check its `<script>` tags) and write code valid for that exact version.\n- Shared Vue components under `protected/views/vue/` are consumed by pages on DIFFERENT Vue versions — a change there must be tested on at least one consumer of each version, or scoped to a page-local copy instead.\n- Vue components are rendered THROUGH PHP views (`views/vue/`) — data flows in via PHP-echoed props/globals; keep that contract, do not convert pages to SPA.\n\n### Database / DDL\n- `protected/migrations/` is NOT a real migrations dir (it points at the prod host). Never create `mYYMMDD_*.php` migrations. Describe the exact DDL (CREATE/ALTER statements) in the PR/issue and hand it off for the deploy host.\n- Remember tenant prefixing when writing DDL for hot tables.\n\n### Git-hosted god files (context discipline)\n- Several files exceed 10k LOC (`ZagruzGroupOverhead.php` ~16.6k, V2/V4 API controllers 10–12k, 8k-LOC print views duplicated across `gps2`/`gps3`). Never rewrite or reformat them; make the smallest targeted edit (grep for the exact function, edit in place) and never let a diff touch unrelated regions of such a file.\n\n### QA / testing reality\n- There is effectively NO test suite (4 PHPUnit files for 1.16M LOC). Do not invent test harnesses; verification = deterministic smoke on the QA box + the Agora test-case pipeline.\n- Playwright dashboard assertion: use `page.title()` — the string \"Дашборд\" appears only in `<title>`, not the body.\n- Base regression scripts (`/api3/*`) require a ROLE=4 mobile agent account (`QA_AGENT_LOGIN`/`QA_AGENT_PASSWORD`); the web admin account is rejected. Without those creds, mark such scripts BLOCKED (not failed); a change that cannot affect stock math is not gated by them.", "qa_manifest": {"auth": {"password": "123456", "username": "demo", "login_path": "/site/login", "pass_field": "LoginForm[password]", "user_field": "LoginForm[username]", "success_contains": "Дашборд"}, "flows": [{"name": "dashboard smoke", "path": "/", "steps": ["open the base URL", "log in if a login form appears (web admin creds from auth above when filled)"], "assert": "page <title> contains 'Дашборд' — assert via page.title(), NOT body text (the string appears only in <title>)"}], "notes": "sd-main is NOT locally runnable — verification happens ONLY against the QA boxes (sdteam.uz). Web admin credentials are not yet documented: when auth creds above are empty, mark auth-gated flows BLOCKED instead of failing them, and say which creds are missing. Primary UI language is Russian. This manifest is a seed — extend routes/flows only with LIVE-VERIFIED entries (an honest small manifest beats a fabricated large one).", "routes": {"dashboard": "/"}, "accounts": [{"note": "required by the /api3/* base regression scripts (getAgentSession → /api3/login). The web admin account is REJECTED there. Until these creds are filled by a human, mark those scripts BLOCKED (never invent credentials, never fail the gate on them).", "role": "agent (ROLE=4, mobile)", "password": "", "username": ""}], "base_url": "https://sandbox.sdteam.uz", "known_issues": ["/api3/login returns HTTP 200 + HTML auth redirect for invalid tokens (not JSON) — check Content-Type before JSON.parse; this is correct behavior, not a bug"]}, "sprint_mode": true, "qa_smoke_url": "https://sandbox.sdteam.uz", "qa_critical_paths": ["create order", "kassa / payments", "warehouse & stock counts"], "config_watchdog_at": "2026-07-07T04:38:05Z"}$sdmain$::jsonb)
ON CONFLICT (id) DO UPDATE SET settings = EXCLUDED.settings, updated_at = now();

